package com.hailiang.handwrite.bean;public class DrawingRecord{public int w,h,left,top,right,bottom;public java.util.List<PathInfo> paths=new java.util.ArrayList<>();public java.util.List<PathInfo> getPathInfoList(){return paths;}public void setPathInfoList(java.util.List<PathInfo> p){paths=p;}public int getRight(){return right;}public int getBottom(){return bottom;}public void setWidth(int n){w=n;}public void setHeight(int n){h=n;}public void setLeft(int n){left=n;}public void setTop(int n){top=n;}public void setRight(int n){right=n;}public void setBottom(int n){bottom=n;}}